from decimal import Decimal, InvalidOperation


def summarize(events):
    totals = {}
    for event in events:
        account = event['account'].strip()
        kind = event['kind']
        try:
            amount = Decimal(event['amount'])
        except (InvalidOperation, ValueError) as exc:
            raise ValueError('invalid amount') from exc
        if (not account or kind not in ('charge', 'refund')
                or not amount.is_finite() or amount < 0
                or amount.as_tuple().exponent < -2):
            raise ValueError('invalid event')
        cents = int(amount * 100) * (-1 if kind == 'refund' else 1)
        total = totals.setdefault(account, {'account': account, 'net_cents': 0, 'entries': 0})
        total['net_cents'] += cents
        total['entries'] += 1
    return {'schema': 2, 'totals': [totals[key] for key in sorted(totals)]}
